#!/usr/bin/env python3
"""Collect the final runs (two FAST + one FULL) into results/SUMMARY.md.  usage: python3 make_summary.py   (Windows side)"""
import json
import os

ROOT = "E:/VPN/multiloc-stand"
RUNS = [("fast1", "быстрый"), ("fast2", "быстрый"), ("full1", "полный")]
rows, suites_all = [], {}
for name, kind in RUNS:
    p = f"{ROOT}/work/out/runs/{name}/results.json"
    if not os.path.exists(p):
        rows.append((name, kind, None))
        continue
    r = json.load(open(p, encoding="utf-8"))
    rows.append((name, kind, r))
    for sname, s in (r.get("suites") or {}).items():
        suites_all.setdefault(sname, {})[name] = s

ok_runs = [n for n, _, r in rows if r and r.get("verdict_ok")]
lines = ["# Итоги стенда мульти-локаций: итоговая версия (22 файла)", "",
         "Дата: 2026-10-11. Каждый прогон: свежий импорт «золотого» образа (прод-подобная база, фича не установлена) → проверка чистоты → установка реальным установщиком → "
         "тесты на реальных процессах → проверка правила владельца (34 пункта). Полный прогон дополнительно: все наборы тестов и перезапуск дистрибутива (как недельный reboot) с проверкой после него.", "",
         "Правило, которое проверяется: **обычная ссылка не меняется ни для кого (никакого переключения по приложению); AUTO и страны — только на отдельной ссылке `…/happ/` "
         "(Happ/INCY) и в списке «All Configs»; бот отдаёт тестеру две ссылки.**", ""]
lines.append(f"**Вердикт серии на итоговой версии (после правок раундов 1–3 аудита Codex): {len(ok_runs)} из {len(RUNS)} прогонов успешны.**" + ("  ✅" if len(ok_runs) == len(RUNS) else "  ⚠️"))
lines += ["", "| прогон | вид | порядок | тестов | время, с | подписки тестера и обычного идентичны (фича выключена) | повтор установки = no-op | verify | после перезапуска | вердикт |",
          "|---|---|---|---:|---:|---|---|---|---|---|"]
yn = lambda v: "—" if v is None else ("да" if v else "НЕТ")  # noqa: E731
for name, kind, r in rows:
    if not r:
        lines.append(f"| {name} | {kind} | — | — | — | — | — | — | — | не выполнен |")
        continue
    lines.append(f"| {name} | {kind} | {r.get('order')} | {r.get('total_tests')} | {r.get('seconds')} | {yn(r.get('golden_installed_off_identical'))} | {yn(r.get('reapply_noop'))} | "
                 f"{yn(r.get('installer_verify_ok'))} | {yn(r.get('post_reboot_smoke_ok'))} | {'✅ OK' if r.get('verdict_ok') else '❌'} |")

DESC = {
    "test_01_unit": "юнит-тесты слоя router, построителя групп и правила «кто видит страны» (только путь /happ и список «All Configs», никакого User-Agent); согласованность «проверки расхождения» установщика со слоем router",
    "test_02_subscription": "подписки по HTTP: обычная ссылка и все форматы у тестера и обычных пользователей штатные (идентичны после нормализации непостоянных полей); /happ/ = 3 кнопки; список «All Configs»; видимость; отказ хуков",
    "test_03_dataplane": "реальный трафик: страна → свои выходы, РФ-адреса напрямую, AUTO по самому быстрому, отказ выхода, резерв, закрытые слоты",
    "test_04_lifecycle": "жизненный цикл пользователей: горячее добавление/удаление во входы без зависимости от статистики, учёт трафика, анти-шаринг",
    "test_05_migration": "миграции и MariaDB 10.11.14 (DDL идемпотентен, FK, кодировки, восстановление из дампа, панель без таблиц)",
    "test_06_installer": "установщик: проверка хешей и отсутствия файлов, идемпотентность, откат (файлы по sha256, БД — схема и число строк), частичное создание таблиц, автооткат на 7 шагах, откат слоя router; незавершённый откат остаётся открытым и дозавершается обычным rollback; router и файлы, изменённые после установки, не теряются",
    "test_07_ui": "минимальный интерфейс по HTTP: страницы, формы, права; кнопка «Применить» отключена и ничего не запускает",
    "test_08_render_reboot": "рендер (xray -test, haproxy -c, nginx -t), точный порядок правил стран по реальному объединённому конфигу, недельный полный install.sh, reload HAProxy без обрыва, окно рестарта hiddify-xray",
    "test_09_router_apply": "быстрый путь apply: один рестарт, готовность, откат, занятый порт, урезанная проверка xray -test",
    "test_10_groups_wire": "три кнопки Happ/INCY на проводе: реальный xray-клиент из JSON, страна не выходит из страны, AUTO по скорости, отказ протокола внутри кнопки",
    "test_11_bot_links": "Telegram-бот: обычному пользователю прежнее сообщение, тестеру две ссылки (обычная + /happ/); обычная ссылка не меняется ни для одного приложения",
    "test_12_blocks": "блокировки: адрес из частной сети и BitTorrent закрываются для профилей стран так же, как для обычных (реальный клиент → цепочка → «интернет» стенда; с калибровкой)",
    "test_zz_smoke_rules": "проверка правила владельца целиком (34 пункта): 10 типов приложений × обычная ссылка, 7 форматов, /happ/, обычный пользователь, «All Configs», сообщения бота",
}
lines += ["", "## Что прошло в каждом прогоне (время в секундах)", "", "| набор | что проверяет | тестов | " + " | ".join(n for n, _, _ in rows) + " |", "|---|---|---:|" + "---:|" * len(rows)]
for sname in sorted(suites_all):
    per = suites_all[sname]
    tests = max((s.get("tests") or 0) for s in per.values())
    cells = []
    for name, _, _ in rows:
        s = per.get(name)
        cells.append("—" if not s else (f"{s['seconds']} ✅" if s.get("ok") else f"{s['seconds']} ❌"))
    lines.append(f"| `{sname}` | {DESC.get(sname, '')} | {tests} | " + " | ".join(cells) + " |")
ROUND2 = """
## Что менялось после раундов 2 и 3 аудита Codex и как это проверено (2026-10-11)
22 файла продукта не менялись с раунда 1 (их SHA256 равны манифесту — `test_06 test_00_payload_integrity`). Менялись установщик (откат, проверки перед изменением, блокировка), тесты и документы. Проверено так:

| что | результат |
|---|---|
| `test_01_unit` (28 тестов; +2: проверка «расхождения» установщика согласована со слоем router, чужие правки замечаются, в том числе в `observatory`) | ✅ во всех прогонах серии |
| `test_06_installer` (24 теста; раунд 2: +4, раунд 3: +8 — пропавший конфиг router; правка `observatory`; убитый процесс сразу после замены файла и после рестарта hiddify-xray; пустой дамп БД при установке; дамп таблиц перед `DROP`; один запуск за раз; нечитаемый `STATE.json`) | ✅ все 24 в чистом клоне золотого образа (546 с), потом в полном прогоне серии; в быстрых — выбранные 9 |
| `test_08 TestRuleOrderOfTheCountryEntrances` (2) и `test_12_blocks` (3): порядок правил стран по реальному объединённому конфигу и блокировки BitTorrent / частной сети | ✅ во всех прогонах серии |
| `smoke_new_rule.py`: правило владельца (34 проверки) | ✅ ALL OK |

Проверки «на зубы»: (1) новый тест отката раунда 2 падает на прежнем установщике; (2) перенос финалов стран перед блокировками ловится BitTorrent-тестом на 6 профилях стран; (3) все 8 новых тестов раунда 3 падают на установщике до раунда 3, каждый по своей причине (`results/mut3-clone.log`, `results/mut3b-clone.log`; тест про `observatory` в общем прогоне упал каскадом, отдельным прогоном — по нужной причине).

Серия по схеме владельца (**2 быстрых + 1 полный**) выполнена на финальной версии установщика (после правок раунда 3): быстрый вид 118 проверок, полный 197. Результаты серии до раундов 2 и 3 сохранены в `results/round2/`, до раунда 1 — в `results/round1/`.
"""
lines += [ROUND2]
lines += ["", "Быстрый вид запускает все лёгкие наборы целиком, из тяжёлых `test_02` и `test_06` — их ключевую часть (список «All Configs» и ссылка /happ/; установщик: идемпотентность, побайтовый откат, незавершённый откат, убитый процесс после замены файла, пустой дамп БД, блокировка, нечитаемое состояние — 9 из 24 тестов), "
          "и не делает перезапуск дистрибутива. Полный вид — всё.", "",
          "## Что нашли по ходу работы (честно)",
          "- Прогоны со случайным порядком нашли три нестабильности **тестовой обвязки** (скачки часов WSL, гонка за свободный порт клиента, нормализация случайного суффикса) — исправлены; ожидание готовности router в коде переведено на монотонные часы.",
          "- Прежние три полных прогона (133 теста) относятся к предыдущей версии (25 файлов); итоговая версия проверена прогонами выше.",
          "- Раунд 3: мой новый тест про `observatory` сначала оставлял на dev-стенде изменённый конфиг router, из-за чего 6 соседних тестов упали (изоляция теста, не продукт); тест исправлен, проверка повторена в чистом клоне. Строка `user@1000.service failed` в быстрых прогонах — шум WSL (есть и в прежних прогонах), в полном прогоне после перезапуска её нет.",
          "- Неудачные/прерванные попытки сохранены в `work/out/runs/*-aborted-*`, `*-superseded-*`, `*-failed-*` и `results/superseded/`.", "",
          "## Файлы", "- `RISKS.md` — риски; `../AUDIT_REQUEST_CODEX.md` — задание на независимый аудит; `../RUNBOOK_DEPLOY.md` — черновик плана окна; `../work/src/diffs/` — полный diff (22 файла).",
          "- `sample-subscription-*` — образцы подписок (синтетические данные стенда, не прод)."]
open(f"{ROOT}/results/SUMMARY.md", "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
print("\n".join(lines[:14]))
